/**
 * Shared vocabulary for a single pitch: what it is, where it went, and when
 * every audible moment of it happens on both clocks.
 */

export type PitchType = "fastball" | "slider" | "curveball" | "changeup";

/**
 * Where the pitch crosses the plate, in **zone units**.
 *
 * Both axes are 0 at dead centre and ±1.0 at the edge of the strike zone (the
 * black). Values beyond ±1 are off the plate; realistic misses reach about ±2.2,
 * which is roughly a pitch two baseballs off the corner.
 *
 * `horizontal` is catcher's view: negative toward third base, positive toward
 * first. That matches "inside / outside" for a right-handed batter; for a lefty
 * the booth must flip those words (see `describeLocation`).
 * `vertical` is negative toward the dirt, positive toward the letters.
 */
export interface PitchLocation {
  horizontal: number;
  vertical: number;
}

/** Widest location the pitch generator will produce; also the pan/filter full-scale. */
export const LOCATION_EXTENT = 2.2;

export interface PitchProfile {
  readonly type: PitchType;
  /** Seconds from release to the plate. Slower pitches give the batter more time. */
  readonly flightSeconds: number;
  readonly velocityMph: number;
  /** Human-readable fragment for the commentary assembler. */
  readonly label: string;
}

/**
 * Every timestamp for one pitch, fixed at scheduling time.
 *
 * The audio-clock fields drive `AudioParam` automation. `perceivedPlateMs` is the
 * same instant as `plateTime`, translated through the ClockBridge into the
 * performance timeline — that is the number a swing is actually measured against,
 * and the reason this struct carries both.
 */
export interface PitchTimeline {
  readonly id: number;
  readonly profile: PitchProfile;
  readonly location: PitchLocation;

  /** Audio clock, seconds. */
  readonly startTime: number;
  readonly releaseTime: number;
  readonly plateTime: number;
  /** When game logic gives up waiting and calls the pitch. */
  readonly resolveTime: number;

  /** Performance clock, milliseconds — when the listener hears the ball arrive. */
  readonly perceivedPlateMs: number;
}

/**
 * The reference beat — fastball flight time, and the interval the windup pulses on.
 *
 * This is the spine of the whole game feel. Asking someone to predict an instant
 * 420 ms after a single cue is a guess; asking them to continue a pulse they have
 * already heard three times is a rhythm, and people are extraordinarily good at
 * rhythm. So the delivery lays down beats at exactly this spacing, the release
 * lands on a beat, and a fastball crosses the plate on the next one.
 *
 * Off-speed pitches are then *defined* as deviations from the established pulse —
 * the changeup arrives a beat-and-a-third late, the curve later still — which is
 * how hitters actually describe them.
 */
export const PITCH_PULSE_SEC = 0.42;

/** Timing thresholds, straight from the brief. */
export const PERFECT_WINDOW_MS = 30;
export const CONTACT_WINDOW_MS = 70;

/**
 * How far either side of the plate a keypress still counts as a swing at *this*
 * pitch. Wider than the contact window on purpose: a swing 150 ms late is a
 * terrible swing, not a non-event, and the batter should be charged a strike.
 */
export const SWING_WINDOW_MS = 250;

/** Extra time held after the plate before the pitch is resolved as a take. */
export const RESOLVE_DELAY_SEC = SWING_WINDOW_MS / 1000 + 0.05;

/**
 * Umpire's view. Corners are strikes, so the zone is a square in zone units and
 * the correct metric is Chebyshev distance, not Euclidean — (1.0, 1.0) is a
 * painted corner, not a ball.
 */
export function isInStrikeZone(location: PitchLocation): boolean {
  return Math.max(Math.abs(location.horizontal), Math.abs(location.vertical)) <= 1;
}

/**
 * Batter's view. Here Euclidean distance is right: a corner really is harder to
 * square up than a pitch on the edge but belt-high, because it is farther from
 * the sweet spot of the swing plane.
 */
export function zoneDistance(location: PitchLocation): number {
  return Math.hypot(location.horizontal, location.vertical);
}

/** Zone units to stereo pan (-1 hard left, +1 hard right), clamped. */
export function locationToPan(location: PitchLocation): number {
  return clamp(location.horizontal / LOCATION_EXTENT, -1, 1);
}

/**
 * Zone units to a filter cutoff in Hz.
 *
 * Height is encoded as brightness: a pitch at the letters is open and airy, one
 * in the dirt is muffled. Exponential because pitch perception is logarithmic —
 * a linear sweep would bunch all the useful discrimination at the top.
 */
export function locationToCutoff(location: PitchLocation, low = 380, high = 5200): number {
  const t = clamp((location.vertical + LOCATION_EXTENT) / (2 * LOCATION_EXTENT), 0, 1);
  return low * Math.pow(high / low, t);
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
