/**
 * Intentional walk — one control books a free pass when the human is pitching.
 * No four-pitch ceremony; count and box score treat it as a single pitch.
 */
export function canIntentionalWalk(args: {
  humanPitching: boolean;
  gameOver: boolean;
  pitchInFlight: boolean;
  practice: boolean;
}): boolean {
  return args.humanPitching && !args.gameOver && !args.pitchInFlight && !args.practice;
}
