/**
 * BR-6 — authored situation challenges (fixed snapshots, seeded RNG, clear win/lose).
 *
 * Coordination: does **not** add a SessionMode. Uses `SessionOptions.challengeId`
 * (+ optional GameSave.campaign `{ kind: "challenge", ... }`) so series / season /
 * playoff / BR-8 stay on their existing mode / campaignKind lanes.
 */

import type { GamePersist, GameSnapshot, Half, PlayReport, Score } from "./GameState.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import type { RoleLock, SessionLength, SessionMode } from "./SessionOptions.ts";
import { AWAY_TEAM, HOME_TEAM } from "./Teams.ts";

export const CHALLENGE_IDS = [
  "hold-ninth",
  "bottom-ninth",
  "escape-act",
  "practice-cage-plus",
  "tie-breaker",
  "traffic-jam",
  "extras-hold",
  "inherited-save",
] as const;

export type ChallengeId = (typeof CHALLENGE_IDS)[number];

export type ChallengeKind = "situation" | "practice";

export interface ChallengeCampaignV1 {
  readonly kind: "challenge";
  readonly v: 1;
  readonly id: ChallengeId;
  readonly seed: number;
  /** Practice cage++ progress (situation challenges ignore these). */
  readonly practicePitchesThrown?: number;
  readonly practiceScore?: number;
}

export interface ChallengeOutcome {
  readonly won: boolean;
  readonly summary: string;
  readonly title: string;
}

export interface ChallengeEvalContext {
  readonly before: GameSnapshot;
  readonly after: GameSnapshot;
  readonly report: PlayReport;
  readonly playerSide: PlayerSide;
}

export interface PracticePitchScore {
  readonly pitchesThrown: number;
  readonly score: number;
  readonly targetPitches: number;
  readonly winScore: number;
}

export interface ChallengePreset {
  readonly id: ChallengeId;
  readonly title: string;
  /** Short gate / picker label. */
  readonly label: string;
  /** Win/lose rules — spoken up front and shown on the end card. */
  readonly rules: string;
  /** One spoken situation line at broadcast start. */
  readonly situationLine: (playerSide: PlayerSide) => string;
  readonly kind: ChallengeKind;
  readonly roleLock: RoleLock;
  readonly length: SessionLength;
  /** Forced session mode while this challenge is active. */
  readonly mode: SessionMode;
  /** Base seed; date-hash challenges may XOR with the day. */
  readonly seed: number;
  readonly startingState: (playerSide: PlayerSide) => GamePersist;
  readonly evaluate: (ctx: ChallengeEvalContext) => ChallengeOutcome | null;
  /** Practice cage++ only. */
  readonly practicePitches?: number;
  readonly practiceWinScore?: number;
}

const EMPTY_BASES = { first: false, second: false, third: false } as const;

function persist(partial: {
  inning: number;
  half: Half;
  outs: number;
  score: Score;
  bases: GamePersist["bases"];
  balls?: number;
  strikes?: number;
  awayBatterIndex?: number;
  homeBatterIndex?: number;
  regulationInnings?: SessionLength;
  homePitcherName?: string;
  awayPitcherName?: string;
}): GamePersist {
  return {
    regulationInnings: partial.regulationInnings ?? 9,
    inning: partial.inning,
    half: partial.half,
    outs: partial.outs,
    balls: partial.balls ?? 0,
    strikes: partial.strikes ?? 0,
    score: { ...partial.score },
    bases: { ...partial.bases },
    gameOver: false,
    awayBatterIndex: partial.awayBatterIndex ?? 0,
    homeBatterIndex: partial.homeBatterIndex ?? 0,
    ...(partial.homePitcherName !== undefined ? { homePitcherName: partial.homePitcherName } : {}),
    ...(partial.awayPitcherName !== undefined ? { awayPitcherName: partial.awayPitcherName } : {}),
  };
}

/** Player score vs opponent for a snapshot. */
export function playerScoreSplit(score: Score, playerSide: PlayerSide): {
  playerRuns: number;
  opponentRuns: number;
} {
  const playerRuns = score[playerSide];
  const opponentRuns = score[playerSide === "home" ? "away" : "home"];
  return { playerRuns, opponentRuns };
}

/**
 * Half where the human is pitching (home pitches top, away pitches bottom).
 */
function pitchingHalf(playerSide: PlayerSide): Half {
  return playerSide === "home" ? "top" : "bottom";
}

function battingHalf(playerSide: PlayerSide): Half {
  return playerSide === "home" ? "bottom" : "top";
}

/** Mulberry32 — deterministic [0,1) stream for fair challenge RNG. */
export function createSeededRng(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function isChallengeId(value: unknown): value is ChallengeId {
  return typeof value === "string" && (CHALLENGE_IDS as readonly string[]).includes(value);
}

/** UTC date key YYYYMMDD for “Today’s broadcast”. */
export function dateHashKey(date: Date = new Date()): number {
  const y = date.getUTCFullYear();
  const m = date.getUTCMonth() + 1;
  const d = date.getUTCDate();
  return y * 10_000 + m * 100 + d;
}

/** Rotate authored challenges by UTC date (stable for the calendar day). */
export function todaysChallengeId(date: Date = new Date()): ChallengeId {
  const key = dateHashKey(date);
  // Skip practice-cage-plus for “today’s broadcast” — keep it a live game situation.
  const liveIds = CHALLENGE_IDS.filter((id) => id !== "practice-cage-plus");
  const index = ((key % liveIds.length) + liveIds.length) % liveIds.length;
  return liveIds[index]!;
}

/**
 * Parse `?challenge=<id>` or `?challenge=today`. Returns null if absent/invalid.
 */
export function parseChallengeQuery(search: string): ChallengeId | "today" | null {
  const raw = search.startsWith("?") ? search.slice(1) : search;
  const params = new URLSearchParams(raw);
  const value = params.get("challenge");
  if (!value) return null;
  if (value === "today") return "today";
  return isChallengeId(value) ? value : null;
}

export function isChallengeCampaign(raw: unknown): raw is ChallengeCampaignV1 {
  if (!raw || typeof raw !== "object") return false;
  const c = raw as Partial<ChallengeCampaignV1>;
  return c.kind === "challenge" && c.v === 1 && isChallengeId(c.id) && typeof c.seed === "number";
}

export function toChallengeCampaign(
  id: ChallengeId,
  seed: number,
  practice?: { pitchesThrown: number; score: number },
): ChallengeCampaignV1 {
  const base: ChallengeCampaignV1 = { kind: "challenge", v: 1, id, seed };
  if (!practice) return base;
  return {
    ...base,
    practicePitchesThrown: practice.pitchesThrown,
    practiceScore: practice.score,
  };
}

export function scorePracticeContact(contact: "solid" | "weak" | "miss" | "take"): number {
  if (contact === "solid") return 3;
  if (contact === "weak") return 1;
  return 0;
}

export function evaluatePracticeCage(
  preset: ChallengePreset,
  pitchesThrown: number,
  score: number,
): ChallengeOutcome | null {
  const target = preset.practicePitches ?? 10;
  const winScore = preset.practiceWinScore ?? 12;
  if (pitchesThrown < target) return null;
  const won = score >= winScore;
  return {
    won,
    title: won ? "Cage complete!" : "Cage over",
    summary: won
      ? `You scored ${score} of ${winScore}+ needed on ${target} pitches. ${preset.rules}`
      : `Score ${score} — needed ${winScore}+ on ${target} pitches. ${preset.rules}`,
  };
}

