export function getChallenge(id: ChallengeId): ChallengePreset {
  return PRESETS[id];
}

export function listChallenges(): readonly ChallengePreset[] {
  return CHALLENGE_IDS.map((id) => PRESETS[id]);
}

/** Resolve gate value `none` | `today` | ChallengeId → concrete id or none. */
export function resolveChallengeGateValue(
  value: string,
  date: Date = new Date(),
): ChallengeId | "none" {
  if (value === "none" || value === "") return "none";
  if (value === "today") return todaysChallengeId(date);
  return isChallengeId(value) ? value : "none";
}

export function applyChallengeSession(
  challengeId: ChallengeId | "none",
): Pick<ChallengePreset, "mode" | "length" | "roleLock"> | null {
  if (challengeId === "none") return null;
  const c = getChallenge(challengeId);
  return { mode: c.mode, length: c.length, roleLock: c.roleLock };
}
