/**
 * GameSave — persist an in-progress game between pitches.
 *
 * Saves after each settled pitch and when the tab hides / user pauses.
 * Never resumes mid-flight; cancel abandons the in-air pitch and keeps the
 * last settled state (already on disk).
 *
 * Optional `campaign` carries series/season/challenge shells (discriminated by `kind`).
 */

import type { DifficultyId } from "./Difficulty.ts";
import { isDifficultyId } from "./Difficulty.ts";
import type { GamePersist } from "./GameState.ts";
import { formatCount } from "./GameState.ts";
import type { LivePersist } from "./LiveStats.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { isPlayerSide } from "./PlayerSide.ts";
import type { SessionOptions } from "./SessionOptions.ts";
import {
  isRoleLock,
  isSessionLength,
  isSessionMode,
  normalizeSessionOptions,
} from "./SessionOptions.ts";
import { isClubShortName } from "./Contest.ts";
import { AWAY_TEAM, HOME_TEAM } from "./Teams.ts";

export const GAME_SAVE_KEY = "botn.gameSave.v1";

export interface GameSaveV1 {
  readonly v: 1;
  readonly savedAt: number;
  readonly playerSide: PlayerSide;
  readonly difficultyId: DifficultyId;
  readonly session: SessionOptions;
  readonly homeTeam: string;
  readonly awayTeam: string;
  readonly game: GamePersist;
  readonly live: LivePersist;
  /**
   * Discriminated campaign wrappers:
   * - `{ kind: "series", ... }` SeriesCampaignV1
   * - `{ kind: "playoff", ... }` PlayoffCampaignV1 (nested series)
   * - `{ kind: "season", season: SeasonPersist }`
   * - `{ kind: "challenge", ... }` ChallengeCampaignV1
   */
  readonly campaign?: unknown;
  /** Optional BR-8 bullpen / fatigue counters — older saves omit this. */
  readonly bullpen?: unknown;
}

function normalizeSession(session: SessionOptions): SessionOptions {
  return normalizeSessionOptions({
    ...session,
    challengeId: session.challengeId ?? "none",
  });
}

export function buildGameSave(args: {
  playerSide: PlayerSide;
  difficultyId: DifficultyId;
  session: SessionOptions;
  game: GamePersist;
  live: LivePersist;
  campaign?: unknown;
  bullpen?: unknown;
  /** Per-game host assignment. Defaults to Pirates home / Phillies away. */
  homeTeam?: string;
  awayTeam?: string;
}): GameSaveV1 {
  const save: GameSaveV1 = {
    v: 1,
    savedAt: Date.now(),
    playerSide: args.playerSide,
    difficultyId: args.difficultyId,
    session: normalizeSession(args.session),
    homeTeam: args.homeTeam ?? HOME_TEAM.shortName,
    awayTeam: args.awayTeam ?? AWAY_TEAM.shortName,
    game: args.game,
    live: args.live,
  };
  let out: GameSaveV1 = save;
  if (args.campaign !== undefined) {
    out = { ...out, campaign: args.campaign };
  }
  if (args.bullpen !== undefined) {
    out = { ...out, bullpen: args.bullpen };
  }
  return out;
}

export function isValidGameSave(raw: unknown): raw is GameSaveV1 {
  if (!raw || typeof raw !== "object") return false;
  const s = raw as Partial<GameSaveV1>;
  if (s.v !== 1) return false;
  if (!isPlayerSide(String(s.playerSide ?? ""))) return false;
  if (!isDifficultyId(String(s.difficultyId ?? ""))) return false;
  if (!s.session || typeof s.session !== "object") return false;
  if (!isSessionMode(s.session.mode)) return false;
  if (!isSessionLength(s.session.length)) return false;
  if (!isRoleLock(s.session.roleLock)) return false;
  if (typeof s.homeTeam !== "string" || typeof s.awayTeam !== "string") return false;
  if (!isClubShortName(s.homeTeam) || !isClubShortName(s.awayTeam)) return false;
  if (s.homeTeam === s.awayTeam) return false;
  if (!s.game || typeof s.game !== "object") return false;
  if (s.game.regulationInnings !== s.session.length) return false;
  if (s.game.gameOver) return false;
  if (!s.live || typeof s.live !== "object") return false;
  if (!Array.isArray(s.live.awayBatters) || !Array.isArray(s.live.homeBatters)) return false;
  return true;
}

export function loadGameSave(): GameSaveV1 | null {
  try {
    const raw = localStorage.getItem(GAME_SAVE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!isValidGameSave(parsed)) return null;
    return {
      ...parsed,
      session: normalizeSession(parsed.session),
    };
  } catch {
    return null;
  }
}

export function writeGameSave(save: GameSaveV1): void {
  if (save.game.gameOver) {
    clearGameSave();
    return;
  }
  try {
    localStorage.setItem(GAME_SAVE_KEY, JSON.stringify(save));
  } catch {
    /* private browsing / quota */
  }
}

export function clearGameSave(): void {
  try {
    localStorage.removeItem(GAME_SAVE_KEY);
  } catch {
    /* ignore */
  }
}

/** Short gate / SR label — "Resume: Bottom 7, 3-2, Pirates 4–3". */
export function describeGameSave(save: GameSaveV1): string {
  const half = save.game.half === "top" ? "Top" : "Bottom";
  const score = `${save.homeTeam} ${save.game.score.home}–${save.game.score.away} ${save.awayTeam}`;
  return `${half} ${save.game.inning}, ${formatCount(save.game.balls, save.game.strikes)}, ${score}`;
}
