/**
 * BR-7 share sheet — radio-card preview + Web Share / copy-link.
 *
 * Patterns borrowed from arcade `src/social/share.js` (native share, copy,
 * platform intent links) but styled with broadcast-theme CSS variables and
 * no arcade purple chrome. No third-party CDNs.
 *
 * Safari: prefer `navigator.share({ title, text, url })` from a user gesture.
 * Chrome desktop: Copy link is primary; native share when the OS exposes it.
 * PNG download is a cheap canvas export of the card (optional, same-origin).
 */

import {
  buildShareCaption,
  formatMomentScore,
  shareDeepLinkFromMoment,
  themeColorsFor,
  type BroadcastMoment,
} from "../social/BroadcastShare.ts";

const STYLE_ID = "botn-share-style";
const OVERLAY_ID = "botn-share-overlay";

const SHARE_TARGETS = [
  { key: "x", label: "X", emoji: "𝕏" },
  { key: "whatsapp", label: "WhatsApp", emoji: "💬" },
  { key: "telegram", label: "Telegram", emoji: "✈️" },
  { key: "facebook", label: "Facebook", emoji: "📘" },
  { key: "reddit", label: "Reddit", emoji: "👽" },
] as const;

function escapeHtml(str: string): string {
  return String(str ?? "").replace(/[&<>"']/g, (match) => {
    switch (match) {
      case "&":
        return "&amp;";
      case "<":
        return "&lt;";
      case ">":
        return "&gt;";
      case '"':
        return "&quot;";
      case "'":
        return "&#39;";
      default:
        return match;
    }
  });
}

function buildShareIntentUrls(url: string, text: string): Record<string, string> {
  const u = encodeURIComponent(url);
  const t = encodeURIComponent(text);
  const textThenUrl = text ? `${t}%20${u}` : u;
  return {
    x: `https://twitter.com/intent/tweet?text=${t}&url=${u}`,
    whatsapp: `https://api.whatsapp.com/send?text=${textThenUrl}`,
    telegram: `https://t.me/share/url?url=${u}&text=${t}`,
    facebook: `https://www.facebook.com/sharer/sharer.php?u=${u}`,
    reddit: `https://www.reddit.com/submit?url=${u}&title=${t}`,
  };
}

export function canNativeShare(): boolean {
  return typeof navigator !== "undefined" && typeof navigator.share === "function";
}

export async function nativeShareBroadcast(opts: {
  title: string;
  text: string;
  url: string;
}): Promise<boolean> {
  if (!canNativeShare()) return false;
  try {
    await navigator.share({ title: opts.title, text: opts.text, url: opts.url });
    return true;
  } catch {
    // User cancelled or share rejected — not an error.
    return false;
  }
}

export async function copyShareText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

function injectStyles(): void {
  if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
    .botn-share-overlay {
      position: fixed; inset: 0; z-index: 10000; display: flex;
      align-items: center; justify-content: center; padding: 16px;
      background: rgba(8, 12, 22, 0.72);
      font-family: system-ui, sans-serif;
    }
    .botn-share-panel {
      width: min(360px, 94vw); max-height: 92vh; overflow: auto;
      background: var(--panel, #162238); color: var(--ink, #f2f5fa);
      border: 2px solid var(--accent, #c41230); border-radius: 10px;
      padding: 16px 16px 18px; position: relative;
      box-shadow: 0 18px 50px rgba(0,0,0,0.55);
    }
    .botn-share-panel h3 {
      margin: 0 0 10px; font-family: var(--display, "Barlow Condensed", sans-serif);
      font-size: 1.15rem; letter-spacing: 0.04em; text-transform: uppercase;
      color: var(--accent, #c41230);
    }
    .botn-radio-card {
      border-radius: 8px; padding: 14px 14px 12px; margin-bottom: 12px;
      border: 1px solid color-mix(in srgb, var(--accent, #c41230) 55%, transparent);
      background: linear-gradient(165deg, var(--bg, #0b1220), var(--panel, #162238));
    }
    .botn-radio-card .botn-rc-brand {
      margin: 0 0 6px; font-size: 0.65rem; letter-spacing: 0.14em;
      text-transform: uppercase; color: var(--warn, #f0c14b); opacity: 0.9;
    }
    .botn-radio-card .botn-rc-drama {
      margin: 0 0 8px; font-family: var(--display, "Barlow Condensed", sans-serif);
      font-size: 1.25rem; line-height: 1.2; font-weight: 700;
      color: var(--ink, #f2f5fa);
    }
    .botn-radio-card .botn-rc-score {
      margin: 0; font-size: 1.6rem; font-weight: 800;
      font-family: var(--display, "Barlow Condensed", sans-serif);
      color: var(--accent, #c41230); letter-spacing: 0.02em;
    }
    .botn-radio-card .botn-rc-meta {
      margin: 6px 0 0; font-size: 0.72rem; color: var(--ink-dim, #8b9bb4);
    }
    .botn-share-url {
      margin: 0 0 12px; font-size: 0.7rem; color: var(--ink-dim, #8b9bb4);
      word-break: break-all;
    }
    .botn-share-native {
      display: block; width: 100%; cursor: pointer; margin-bottom: 10px;
      border: none; border-radius: 8px; padding: 11px; font-weight: 800; font-size: 0.9rem;
      font-family: inherit; color: #0b1220; background: var(--accent, #c41230);
    }
    .botn-share-grid {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; margin-bottom: 10px;
    }
    .botn-share-target {
      display: flex; flex-direction: column; align-items: center; gap: 3px;
      text-decoration: none; color: var(--ink, #f2f5fa); font-size: 0.58rem;
      font-weight: 600; padding: 7px 2px; border-radius: 8px;
      background: color-mix(in srgb, var(--ink, #fff) 6%, transparent);
      border: 1px solid color-mix(in srgb, var(--ink, #fff) 12%, transparent);
    }
    .botn-share-target span.emoji { font-size: 1.05rem; line-height: 1; }
    .botn-share-row { display: flex; gap: 8px; flex-wrap: wrap; }
    .botn-share-copy, .botn-share-png {
      flex: 1; min-width: 8rem; cursor: pointer; border-radius: 8px; padding: 10px;
      font-weight: 700; font-size: 0.8rem; font-family: inherit;
      color: var(--ink, #f2f5fa);
      background: color-mix(in srgb, var(--accent, #c41230) 18%, transparent);
      border: 1.5px solid color-mix(in srgb, var(--accent, #c41230) 55%, transparent);
    }
    .botn-share-close {
      position: absolute; top: 6px; right: 10px; cursor: pointer;
      background: none; border: none; color: var(--ink-dim, #8b9bb4);
      font-size: 1.35rem; font-weight: 700; line-height: 1;
    }
  `;
  document.head.appendChild(style);
}

/** Cheap canvas PNG of the radio card (same-origin download; no CDN). */
export async function downloadMomentPng(moment: BroadcastMoment): Promise<boolean> {
  if (typeof document === "undefined") return false;
  const theme = themeColorsFor(moment.themeId);
  const canvas = document.createElement("canvas");
  canvas.width = 720;
  canvas.height = 420;
  const ctx = canvas.getContext("2d");
  if (!ctx) return false;

  const grad = ctx.createLinearGradient(0, 0, 720, 420);
  grad.addColorStop(0, theme.background);
  grad.addColorStop(1, theme.panel);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 720, 420);

  ctx.strokeStyle = theme.accent;
  ctx.lineWidth = 4;
  ctx.strokeRect(18, 18, 684, 384);

  ctx.fillStyle = theme.warning;
  ctx.font = "600 18px system-ui, sans-serif";
  ctx.fillText("BOTTOM OF THE NINTH", 48, 70);

  ctx.fillStyle = theme.score;
  ctx.font = "700 36px system-ui, sans-serif";
  wrapText(ctx, moment.dramaLine, 48, 130, 624, 42);

  ctx.fillStyle = theme.accent;
  ctx.font = "800 64px system-ui, sans-serif";
  ctx.fillText(formatMomentScore(moment), 48, 280);

  ctx.fillStyle = theme.score;
  ctx.globalAlpha = 0.75;
  ctx.font = "400 18px system-ui, sans-serif";
  const meta = [
    `${moment.homeShort} vs ${moment.awayShort}`,
    `${moment.innings} inn.`,
    moment.timingSummary && !moment.timingSummary.startsWith("No timed")
      ? moment.timingSummary
      : "",
  ]
    .filter(Boolean)
    .join("  ·  ");
  ctx.fillText(meta.slice(0, 72), 48, 340);
  ctx.globalAlpha = 1;

  return await new Promise((resolve) => {
    canvas.toBlob((blob) => {
      if (!blob) {
        resolve(false);
        return;
      }
      const a = document.createElement("a");
      const objectUrl = URL.createObjectURL(blob);
      a.href = objectUrl;
      a.download = "bottom-of-the-ninth-broadcast.png";
      a.click();
      URL.revokeObjectURL(objectUrl);
      resolve(true);
    }, "image/png");
  });
}

function wrapText(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
): void {
  const words = text.split(/\s+/);
  let line = "";
  let yy = y;
  for (const word of words) {
    const test = line ? `${line} ${word}` : word;
    if (ctx.measureText(test).width > maxWidth && line) {
      ctx.fillText(line, x, yy);
      line = word;
      yy += lineHeight;
    } else {
      line = test;
    }
  }
  if (line) ctx.fillText(line, x, yy);
}

export interface OpenShareSheetOptions {
  readonly moment: BroadcastMoment;
  readonly href: string;
  /** Called after the overlay is mounted (booth line hook). */
  readonly onOpened?: () => void;
}

/**
 * Open the share sheet with a radio-card preview.
 * Returns the overlay element, or null in non-DOM environments.
 */
export function openBroadcastShareSheet(opts: OpenShareSheetOptions): HTMLElement | null {
  if (typeof document === "undefined") return null;
  injectStyles();
  document.getElementById(OVERLAY_ID)?.remove();

  const { moment } = opts;
  const url = shareDeepLinkFromMoment(moment, opts.href);
  const caption = buildShareCaption(moment);
  const intents = buildShareIntentUrls(url, caption);
  const theme = themeColorsFor(moment.themeId);

  const overlay = document.createElement("div");
  overlay.id = OVERLAY_ID;
  overlay.className = "botn-share-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", "Share this broadcast");

  const timingMeta =
    moment.timingSummary && !moment.timingSummary.startsWith("No timed")
      ? escapeHtml(moment.timingSummary)
      : escapeHtml(moment.modeLabel);

  const targetsMarkup = SHARE_TARGETS.map(
    (target) => `
    <a class="botn-share-target" href="${escapeHtml(intents[target.key] ?? "#")}" target="_blank" rel="noopener noreferrer" data-target="${target.key}">
      <span class="emoji" aria-hidden="true">${target.emoji}</span>${escapeHtml(target.label)}
    </a>`,
  ).join("");

  const nativeMarkup = canNativeShare()
    ? '<button type="button" class="botn-share-native" data-action="native">Share…</button>'
    : "";

  overlay.innerHTML = `
    <div class="botn-share-panel" style="--accent:${theme.accent};--panel:${theme.panel};--bg:${theme.background};--ink:${theme.score};--warn:${theme.warning}">
      <button type="button" class="botn-share-close" aria-label="Close">×</button>
      <h3>Share this broadcast</h3>
      <div class="botn-radio-card" aria-hidden="true">
        <p class="botn-rc-brand">Live from the booth</p>
        <p class="botn-rc-drama">${escapeHtml(moment.dramaLine)}</p>
        <p class="botn-rc-score">${escapeHtml(formatMomentScore(moment))}</p>
        <p class="botn-rc-meta">${escapeHtml(moment.homeShort)} vs ${escapeHtml(moment.awayShort)} · ${moment.innings} inn.${timingMeta ? ` · ${timingMeta}` : ""}</p>
      </div>
      <p class="botn-share-url">${escapeHtml(url)}</p>
      ${nativeMarkup}
      <div class="botn-share-grid">${targetsMarkup}</div>
      <div class="botn-share-row">
        <button type="button" class="botn-share-copy" data-action="copy">Copy link</button>
        <button type="button" class="botn-share-png" data-action="png">Save card PNG</button>
      </div>
    </div>
  `;

  const close = () => overlay.remove();
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector(".botn-share-close")?.addEventListener("click", close);

  const nativeBtn = overlay.querySelector<HTMLButtonElement>('[data-action="native"]');
  nativeBtn?.addEventListener("click", async () => {
    const ok = await nativeShareBroadcast({
      title: "Bottom of the Ninth",
      text: caption,
      url,
    });
    if (ok) close();
  });

  const copyBtn = overlay.querySelector<HTMLButtonElement>('[data-action="copy"]');
  copyBtn?.addEventListener("click", async () => {
    const payload = `${caption}\n${url}`;
    const copied = await copyShareText(payload);
    if (copyBtn) copyBtn.textContent = copied ? "Copied!" : "Copy link";
  });

  const pngBtn = overlay.querySelector<HTMLButtonElement>('[data-action="png"]');
  pngBtn?.addEventListener("click", async () => {
    const ok = await downloadMomentPng(moment);
    if (pngBtn) pngBtn.textContent = ok ? "Saved" : "Save card PNG";
  });

  document.body.appendChild(overlay);
  opts.onOpened?.();
  queueMicrotask(() => {
    const focusTarget =
      nativeBtn ?? overlay.querySelector<HTMLButtonElement>('[data-action="copy"]');
    focusTarget?.focus();
  });
  return overlay;
}
