/**
 * SeasonState — thin W–L schedule of N exhibition games *or* Bo3 series vs the other club.
 *
 * One live game at a time; mid-game resume stays on GameSave. Season meta lives
 * in `botn.season.v1` and is mirrored on `GameSave.campaign` when a game is saved.
 *
 * Season-of-series nests the in-progress SeriesCampaign on the season blob so
 * refresh mid-series restores both standings and the current series score.
 */

import type { DifficultyId } from "./Difficulty.ts";
import { isDifficultyId } from "./Difficulty.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { isPlayerSide } from "./PlayerSide.ts";
import type { RoleLock, SeasonUnit, SessionLength } from "./SessionOptions.ts";
import { isRoleLock, isSeasonUnit, isSessionLength } from "./SessionOptions.ts";
import {
  SeriesState,
  isSeriesCampaign,
  type SeriesCampaignV1,
  type SeriesGameResult,
} from "./SeriesState.ts";
import { isSeasonSlash, type SeasonSlashV1 } from "./SeasonSlash.ts";

export type { SeasonSlashV1 } from "./SeasonSlash.ts";

export const SEASON_SAVE_KEY = "botn.season.v1";

/** 3 for short series seasons; 6 / 12 for game or series slates. */
export type SeasonScheduleLength = 3 | 6 | 12;
export type { SeasonUnit };

export interface SeasonPersist {
  readonly v: 1;
  readonly scheduleLength: SeasonScheduleLength;
  /** Defaults to "game" when omitted (older saves). */
  readonly unit: SeasonUnit;
  readonly gamesPlayed: number;
  readonly wins: number;
  readonly losses: number;
  /** 0-based index of the current (or next) slot in the schedule. */
  readonly currentGameIndex: number;
  readonly playerSide: PlayerSide;
  readonly length: SessionLength;
  readonly roleLock: RoleLock;
  readonly difficultyId: DifficultyId;
  /**
   * In-progress Bo3 when unit === "series". Null/omitted between series or for
   * game seasons. Nested `kind: "series"` campaign — not written to botn.series.v1.
   */
  readonly currentSeries?: SeriesCampaignV1 | null;
  /** Season-long box slash. Omitted on older saves / new seasons. */
  readonly slash?: SeasonSlashV1 | null;
}

/** Discriminated campaign blob stored on GameSaveV1.campaign. */
export interface SeasonCampaign {
  readonly kind: "season";
  readonly season: SeasonPersist;
}

export function isSeasonScheduleLength(value: unknown): value is SeasonScheduleLength {
  return value === 3 || value === 6 || value === 12;
}

export function createSeason(args: {
  scheduleLength: SeasonScheduleLength;
  playerSide: PlayerSide;
  length: SessionLength;
  roleLock: RoleLock;
  difficultyId: DifficultyId;
  unit?: SeasonUnit;
}): SeasonPersist {
  const unit = args.unit ?? "game";
  const base: SeasonPersist = {
    v: 1,
    scheduleLength: args.scheduleLength,
    unit,
    gamesPlayed: 0,
    wins: 0,
    losses: 0,
    currentGameIndex: 0,
    playerSide: args.playerSide,
    length: args.length,
    roleLock: args.roleLock,
    difficultyId: args.difficultyId,
  };
  if (unit !== "series") return base;
  const series = SeriesState.create({
    playerSide: args.playerSide,
    length: args.length,
    roleLock: args.roleLock,
    difficultyId: args.difficultyId,
    bestOf: 3,
  });
  return { ...base, currentSeries: series.toCampaign() };
}

export function isValidSeasonPersist(raw: unknown): raw is SeasonPersist {
  if (!raw || typeof raw !== "object") return false;
  const s = raw as Partial<SeasonPersist>;
  if (s.v !== 1) return false;
  if (!isSeasonScheduleLength(s.scheduleLength)) return false;
  const unit: SeasonUnit = s.unit === undefined ? "game" : s.unit;
  if (!isSeasonUnit(unit)) return false;
  if (!Number.isInteger(s.gamesPlayed) || (s.gamesPlayed as number) < 0) return false;
  if (!Number.isInteger(s.wins) || (s.wins as number) < 0) return false;
  if (!Number.isInteger(s.losses) || (s.losses as number) < 0) return false;
  if (!Number.isInteger(s.currentGameIndex) || (s.currentGameIndex as number) < 0) return false;
  if ((s.gamesPlayed as number) > s.scheduleLength) return false;
  if ((s.wins as number) + (s.losses as number) !== s.gamesPlayed) return false;
  if ((s.currentGameIndex as number) > s.scheduleLength) return false;
  if (!isPlayerSide(String(s.playerSide ?? ""))) return false;
  if (!isSessionLength(s.length)) return false;
  if (!isRoleLock(s.roleLock)) return false;
  if (!isDifficultyId(String(s.difficultyId ?? ""))) return false;
  if (s.currentSeries != null && !isSeriesCampaign(s.currentSeries)) return false;
  if (unit === "game" && s.currentSeries != null) return false;
  if (s.slash != null && !isSeasonSlash(s.slash)) return false;
  return true;
}

/** Normalize older saves that omit `unit`. */
export function normalizeSeasonPersist(raw: SeasonPersist): SeasonPersist {
  const unit = raw.unit ?? "game";
  if (unit === "game") {
    const { currentSeries: _drop, ...rest } = raw as SeasonPersist & {
      currentSeries?: SeriesCampaignV1 | null;
    };
    return { ...rest, unit: "game" };
  }
  return {
    ...raw,
    unit: "series",
    currentSeries: raw.currentSeries ?? null,
  };
}

export function isSeasonCampaign(raw: unknown): raw is SeasonCampaign {
  if (!raw || typeof raw !== "object") return false;
  const c = raw as { kind?: unknown; season?: unknown };
  return c.kind === "season" && isValidSeasonPersist(c.season);
}

export function toSeasonCampaign(season: SeasonPersist): SeasonCampaign {
  return { kind: "season", season: normalizeSeasonPersist(season) };
}

export function isSeasonComplete(season: SeasonPersist): boolean {
  return season.gamesPlayed >= season.scheduleLength;
}

export function seasonSlotNoun(season: SeasonPersist): "Game" | "Series" {
  return (season.unit ?? "game") === "series" ? "Series" : "Game";
}

/**
 * Record a finished schedule slot (single game, or a completed series).
 * Ties count as neither win nor loss but still consume a schedule slot.
 */
export function recordSeasonGameResult(
  season: SeasonPersist,
  result: "win" | "loss" | "tie",
): SeasonPersist {
  if (isSeasonComplete(season)) return season;
  const wins = season.wins + (result === "win" ? 1 : 0);
  const losses = season.losses + (result === "loss" ? 1 : 0);
  const gamesPlayed = season.gamesPlayed + 1;
  const normalized = normalizeSeasonPersist(season);
  const next: SeasonPersist = {
    v: 1,
    scheduleLength: normalized.scheduleLength,
    unit: normalized.unit,
    wins,
    losses,
    gamesPlayed,
    currentGameIndex: Math.min(gamesPlayed, season.scheduleLength),
    playerSide: normalized.playerSide,
    length: normalized.length,
    roleLock: normalized.roleLock,
    difficultyId: normalized.difficultyId,
    ...(normalized.slash ? { slash: normalized.slash } : {}),
  };
  // Open the next Bo3 shell when more series remain.
  if (next.unit === "series" && !isSeasonComplete(next)) {
    const series = SeriesState.create({
      playerSide: next.playerSide,
      length: next.length,
      roleLock: next.roleLock,
      difficultyId: next.difficultyId,
      bestOf: 3,
    });
    return { ...next, currentSeries: series.toCampaign() };
  }
  if (next.unit === "series") {
    return { ...next, currentSeries: null };
  }
  return next;
}

/** Ensure a series shell exists for season-of-series (fresh start / resume repair). */
export function ensureSeasonSeries(season: SeasonPersist): SeasonPersist {
  const normalized = normalizeSeasonPersist(season);
  if (normalized.unit !== "series" || isSeasonComplete(normalized)) return normalized;
  if (normalized.currentSeries && isSeriesCampaign(normalized.currentSeries)) {
    return normalized;
  }
  const series = SeriesState.create({
    playerSide: normalized.playerSide,
    length: normalized.length,
    roleLock: normalized.roleLock,
    difficultyId: normalized.difficultyId,
    bestOf: 3,
  });
  return { ...normalized, currentSeries: series.toCampaign() };
}

export function seasonSeriesState(season: SeasonPersist): SeriesState | null {
  const normalized = normalizeSeasonPersist(season);
  if (normalized.unit !== "series" || !normalized.currentSeries) return null;
  return isSeriesCampaign(normalized.currentSeries)
    ? new SeriesState(normalized.currentSeries)
    : null;
}

/**
 * Record one contest inside a season-of-series slot.
 * Returns updated season + whether the *series* clinched and whether the *season* finished.
 */
export function recordSeasonSeriesGame(
  season: SeasonPersist,
  result: SeriesGameResult,
): {
  season: SeasonPersist;
  seriesFinished: boolean;
  seasonFinished: boolean;
  series: SeriesState;
} {
  let working = ensureSeasonSeries(season);
  const series = seasonSeriesState(working);
  if (!series) {
    return {
      season: working,
      seriesFinished: false,
      seasonFinished: isSeasonComplete(working),
      series: SeriesState.create({
        playerSide: working.playerSide,
        length: working.length,
        roleLock: working.roleLock,
        difficultyId: working.difficultyId,
      }),
    };
  }
  const seriesFinished = series.recordGame(result);
  working = { ...working, currentSeries: series.toCampaign() };
  if (!seriesFinished) {
    return { season: working, seriesFinished: false, seasonFinished: false, series };
  }
  const playerWon = series.playerWonSeries();
  const winner = series.winnerSide();
  const slotResult: "win" | "loss" | "tie" =
    winner === null ? "tie" : playerWon ? "win" : "loss";
  working = recordSeasonGameResult(working, slotResult);
  return {
    season: working,
    seriesFinished: true,
    seasonFinished: isSeasonComplete(working),
    series,
  };
}

/** "Game 3 of 6" / "Series 3 of 6" — 1-based display for the current/next slot. */
export function describeSeasonGameSlot(season: SeasonPersist): string {
  const noun = seasonSlotNoun(season);
  if (isSeasonComplete(season)) {
    return `Season complete — ${season.scheduleLength} of ${season.scheduleLength}`;
  }
  const gameNumber = Math.min(season.currentGameIndex, season.scheduleLength - 1) + 1;
  return `${noun} ${gameNumber} of ${season.scheduleLength}`;
}

/** Spoken / SR standings line. */
export function describeSeasonStandings(season: SeasonPersist): string {
  const record = `${season.wins} and ${season.losses}`;
  const unitNote =
    (season.unit ?? "game") === "series" ? " (best-of-3 series)" : "";
  if (isSeasonComplete(season)) {
    return `Final season record: ${record}${unitNote}.`;
  }
  if (season.gamesPlayed === 0) {
    return `Season standings: ${record}. ${describeSeasonGameSlot(season)}.`;
  }
  return `Season record: ${record}. ${describeSeasonGameSlot(season)}.`;
}

/** Compact label for the end card / live status. */
export function describeSeasonRecordShort(season: SeasonPersist): string {
  return `${season.wins}–${season.losses}`;
}

/** Live / SR campaign line including nested series score when applicable. */
export function describeSeasonCampaignLine(season: SeasonPersist): string {
  const standings = describeSeasonStandings(season);
  const series = seasonSeriesState(season);
  if (!series || series.isComplete()) return standings;
  return `${standings} ${series.scoreLine()}`;
}

export function loadSeason(): SeasonPersist | null {
  try {
    const raw = localStorage.getItem(SEASON_SAVE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!isValidSeasonPersist(parsed)) return null;
    return normalizeSeasonPersist(parsed);
  } catch {
    return null;
  }
}

export function writeSeason(season: SeasonPersist): void {
  try {
    localStorage.setItem(SEASON_SAVE_KEY, JSON.stringify(normalizeSeasonPersist(season)));
  } catch {
    /* private browsing / quota */
  }
}

export function clearSeason(): void {
  try {
    localStorage.removeItem(SEASON_SAVE_KEY);
  } catch {
    /* ignore */
  }
}

/** Prefer dedicated season key; fall back to campaign blob on a game save. */
export function resolveSeasonFromStorage(campaign: unknown): SeasonPersist | null {
  const fromKey = loadSeason();
  if (fromKey) return fromKey;
  if (isSeasonCampaign(campaign)) return normalizeSeasonPersist(campaign.season);
  return null;
}
