import type { SwingJudgment } from "../timing/SwingJudge.ts";
import type { BatterRatings } from "./Player.ts";
import { ratingFactor } from "./Player.ts";
import type { Rng } from "./PitchSelector.ts";

/**
 * OutcomeResolver — turns a swing verdict into a baseball play.
 *
 * The judge already decided how well the ball was struck; this decides what
 * happened to it. Contact quality sets the distribution and the RNG picks from it,
 * which is the honest model: two identically-struck balls do not produce identical
 * results, and a game where they did would feel wrong long before anyone could say why.
 * Batter power/speed tilt XBH and bloop rates without replacing timing skill.
 */

export type PlayResult =
  | "home-run"
  | "double"
  | "single"
  | "line-out"
  | "fly-out"
  | "ground-out"
  | "pop-up"
  | "foul-ball"
  | "swinging-strike"
  | "called-strike"
  | "ball";

const HITS: ReadonlySet<PlayResult> = new Set<PlayResult>(["home-run", "double", "single"]);
const OUTS: ReadonlySet<PlayResult> = new Set<PlayResult>(["line-out", "fly-out", "ground-out", "pop-up"]);

export function isHit(result: PlayResult): boolean {
  return HITS.has(result);
}

export function isBattedOut(result: PlayResult): boolean {
  return OUTS.has(result);
}

export function isBallInPlay(result: PlayResult): boolean {
  return isHit(result) || isBattedOut(result);
}

export function resolvePlay(
  judgment: SwingJudgment,
  rng: Rng = Math.random,
  batter?: BatterRatings,
): PlayResult {
  if (!judgment.swung) {
    return judgment.inStrikeZone ? "called-strike" : "ball";
  }

  const q = judgment.contactQuality;
  const powerF = ratingFactor(batter?.power ?? 70, 0.55);
  const speedF = ratingFactor(batter?.speed ?? 70, 0.35);

  switch (judgment.contact) {
    case "miss":
      return "swinging-strike";

    case "foul-tip":
      return "foul-ball";

    case "weak": {
      // Weak contact is mostly foul balls — which is exactly what the brief's
      // 30–70 ms band describes, and what mistimed swings actually produce.
      const roll = rng();
      if (roll < 0.42) return "foul-ball";
      // Speed helps bloops fall in.
      if (roll < 0.52 + 0.08 * (speedF - 1) && q > 0.32) return "single";
      if (roll < 0.74) return "ground-out";
      if (roll < 0.9) return "pop-up";
      return "fly-out";
    }

    case "solid": {
      // Squared up. Quality shifts the whole distribution rather than acting as a
      // hard threshold, so a 0.9 is usually but not always better than a 0.8.
      // Power rating stretches HR/XBH weight for sluggers vs contact hitters.
      // Kept cooler than early arcade weights — avg perfect contact was ~43% HR.
      const roll = rng();
      const power = ((q - 0.55) / 0.45) * powerF;
      if (roll < 0.05 + 0.18 * power) return "home-run";
      if (roll < 0.16 + 0.28 * power) return "double";
      if (roll < 0.48 + 0.22 * Math.min(1.15, power)) return "single";
      return rng() < 0.55 ? "line-out" : "fly-out";
    }
  }
}

/** Where the ball was hit, from the spray value carried on the swing. */
export function describeField(spray: number, batterHanded: "R" | "L" = "R"): string {
  // Spray is -1 pulled to +1 opposite. A right-handed batter pulls to left field.
  const pulledLeft = batterHanded === "R";
  if (spray < -0.45) return pulledLeft ? "down the left field line" : "down the right field line";
  if (spray < -0.15) return pulledLeft ? "into left field" : "into right field";
  if (spray > 0.45) return pulledLeft ? "the other way, down the right field line" : "the other way, down the left field line";
  if (spray > 0.15) return pulledLeft ? "to right field" : "to left field";
  return "up the middle";
}

/** Crowd excitement (1–5) warranted by a result. */
export function excitementFor(result: PlayResult): 1 | 2 | 3 | 4 | 5 {
  switch (result) {
    case "home-run":
      return 5;
    case "double":
      return 4;
    case "single":
      return 4;
    case "swinging-strike":
    case "called-strike":
      return 3;
    case "line-out":
    case "fly-out":
    case "ground-out":
    case "pop-up":
      return 3;
    case "foul-ball":
      return 2;
    case "ball":
      return 2;
  }
}
