import type { BaseState } from "./GameState.ts";
import { ratingFactor } from "./Player.ts";
import type { Rng } from "./PitchSelector.ts";

/**
 * Thin steal of second — runner on first, second open, 0–1 out.
 * No hit-and-run tree; one attempt per plate appearance.
 */
export const STEAL_CONFIG = {
  /** AI try rate at speed 70. Fast runners nudge up; still uncommon. */
  aiBaseRate: 0.07,
  /** Safe rate at speed 70. */
  successAtAverage: 0.64,
} as const;

export function stealSituation(bases: BaseState, outs: number): boolean {
  return Boolean(bases.first) && !bases.second && outs >= 0 && outs < 2;
}

export function applyStealToBases(bases: BaseState, success: boolean): BaseState {
  if (success) {
    return { first: false, second: true, third: bases.third };
  }
  return { first: false, second: false, third: bases.third };
}

export function aiStealAttemptChance(runnerSpeed: number, batterSpeed: number): number {
  const runnerF = ratingFactor(runnerSpeed, 0.5);
  const batterF = ratingFactor(batterSpeed, 0.15);
  return clamp01(STEAL_CONFIG.aiBaseRate * runnerF * batterF, 0.02, 0.14);
}

export function stealSuccessChance(runnerSpeed: number, batterSpeed: number): number {
  const runnerF = ratingFactor(runnerSpeed, 0.45);
  const batterF = ratingFactor(batterSpeed, 0.12);
  const attention = 0.94 + 0.06 * batterF;
  return clamp01(STEAL_CONFIG.successAtAverage * runnerF * attention, 0.35, 0.85);
}

export function shouldAiAttemptSteal(args: {
  runnerSpeed: number;
  batterSpeed: number;
  rng: Rng;
}): boolean {
  return args.rng() < aiStealAttemptChance(args.runnerSpeed, args.batterSpeed);
}

export function resolveStealSuccess(args: {
  runnerSpeed: number;
  batterSpeed: number;
  rng: Rng;
}): boolean {
  return args.rng() < stealSuccessChance(args.runnerSpeed, args.batterSpeed);
}

export function canHumanSendRunner(args: {
  batting: boolean;
  gameOver: boolean;
  situation: boolean;
  alreadyTriedThisAb: boolean;
  pitchInFlight: boolean;
  practice: boolean;
}): boolean {
  return (
    args.batting &&
    !args.gameOver &&
    args.situation &&
    !args.alreadyTriedThisAb &&
    !args.pitchInFlight &&
    !args.practice
  );
}

function clamp01(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}
