/**
 * BR-7 — Shareable broadcast moments (pure builders).
 *
 * No DOM / navigator here so Vitest can cover URL + drama-line logic.
 * Sheet UI lives in `src/ui/ShareSheet.ts`. CSP-safe: no third-party CDNs;
 * only `navigator.share` / clipboard / same-origin links.
 *
 * Smoke notes (Safari + Chrome):
 * - Mobile Safari: Web Share API is the happy path; clipboard needs the tap
 *   gesture (Share CTA). File/PNG share via `canShare({ files })` is flaky —
 *   we offer download, not file-share, by default.
 * - Desktop Chrome: native share may exist (Windows) but Copy link is the
 *   reliable fallback. Absolute URLs remount on arcade `/baseballradio/` and
 *   local `./` (vite `base: "./"`).
 */

import { isChallengeId, type ChallengeId } from "../game/Challenges.ts";
import { BROADCAST_THEMES } from "../ui/Prefs.ts";

export type SeriesQuery = "bo3";

export interface BroadcastMoment {
  readonly playerRuns: number;
  readonly opponentRuns: number;
  readonly innings: number;
  readonly won: boolean;
  /** Radio-card headline — walk-off / series / challenge beat. */
  readonly dramaLine: string;
  /** e.g. "Timing: 14 swings, 12 ms average." — omit empty/"No timed" in captions. */
  readonly timingSummary: string;
  readonly modeLabel: string;
  readonly challengeId?: ChallengeId;
  /** When the moment came from a Best-of-3 series session. */
  readonly seriesBo3?: boolean;
  readonly themeId: string;
  readonly homeShort: string;
  readonly awayShort: string;
}

export interface DramaLineInput {
  readonly won: boolean;
  readonly tied?: boolean;
  readonly walkOff?: boolean;
  readonly inning: number;
  /** Short name of the club that won (home or away). */
  readonly winnerShort?: string;
  readonly playerRuns: number;
  readonly opponentRuns: number;
  /** Challenge end-card title, if any. */
  readonly challengeTitle?: string;
  readonly challengeSummary?: string;
  /** Series clinch / break line when series mode finished a contest. */
  readonly seriesLine?: string;
  readonly seriesFinished?: boolean;
}

const SHARE_BOOTH_LINES = [
  "Send it to the group chat…",
  "Pass the broadcast along…",
  "Share this one with a friend…",
  "Tape this call for the group…",
] as const;

/** Spoken booth one-liner when the share sheet opens. */
export function shareBoothLine(rng: () => number = Math.random): string {
  const i = Math.floor(rng() * SHARE_BOOTH_LINES.length) % SHARE_BOOTH_LINES.length;
  return SHARE_BOOTH_LINES[i]!;
}

/** Inning as a radio ordinal word when common; else "Nth". */
export function inningWord(inning: number): string {
  const words: Record<number, string> = {
    1: "first",
    2: "second",
    3: "third",
    4: "fourth",
    5: "fifth",
    6: "sixth",
    7: "seventh",
    8: "eighth",
    9: "ninth",
    10: "tenth",
    11: "eleventh",
    12: "twelfth",
  };
  return words[inning] ?? `${inning}th`;
}

/**
 * Build the radio-card drama line (not a generic score dump).
 * Prefers challenge / series / walk-off beats when present.
 */
export function buildDramaLine(input: DramaLineInput): string {
  if (input.challengeTitle) {
    const beat = input.challengeSummary?.trim();
    if (beat && beat.length < 120) return beat;
    return input.challengeTitle;
  }
  if (input.seriesFinished && input.seriesLine) {
    return input.seriesLine;
  }
  if (input.walkOff && input.winnerShort) {
    return `${input.winnerShort} walk it off in the ${inningWord(input.inning)}`;
  }
  if (input.tied) {
    return `Final: tied ${input.playerRuns}–${input.opponentRuns}`;
  }
  if (input.winnerShort) {
    const high = Math.max(input.playerRuns, input.opponentRuns);
    const low = Math.min(input.playerRuns, input.opponentRuns);
    return `${input.winnerShort} take it, ${high}–${low}`;
  }
  if (input.won) {
    return `You win it, ${input.playerRuns}–${input.opponentRuns}`;
  }
  return `Ballgame, ${input.playerRuns}–${input.opponentRuns}`;
}

/**
 * Parse `?series=bo3` (Best-of-3 remount). Returns null if absent/invalid.
 * Challenge query wins when both are present (mutual exclusion at the gate).
 */
export function parseSeriesQuery(search: string): SeriesQuery | null {
  const raw = search.startsWith("?") ? search.slice(1) : search;
  const params = new URLSearchParams(raw);
  const value = params.get("series");
  if (!value) return null;
  if (value === "bo3" || value === "3" || value === "best-of-3") return "bo3";
  return null;
}

export interface ShareUrlOptions {
  /** Full page href (pass `window.location.href` in the browser). */
  readonly href: string;
  readonly challengeId?: ChallengeId | null;
  readonly series?: SeriesQuery | null;
}

/**
 * Deep link that remounts a useful gate state.
 * Shape: `/baseballradio/?challenge=<id>` or `?series=bo3` (relative `./` ok locally).
 */
export function buildBroadcastShareUrl(opts: ShareUrlOptions): string {
  let url: URL;
  try {
    url = new URL(opts.href);
  } catch {
    url = new URL(opts.href, "https://games.aiandsons.io/baseballradio/");
  }
  // Drop prior query so a finished challenge share doesn't keep stale params.
  url.search = "";
  url.hash = "";
  if (opts.challengeId && isChallengeId(opts.challengeId)) {
    url.searchParams.set("challenge", opts.challengeId);
  } else if (opts.series === "bo3") {
    url.searchParams.set("series", "bo3");
  }
  return url.toString();
}

/** Caption for Web Share / clipboard (drama + score; URL appended separately). */
export function buildShareCaption(moment: BroadcastMoment): string {
  const score = `Final ${moment.playerRuns}–${moment.opponentRuns}`;
  const bits = [moment.dramaLine, score];
  if (moment.timingSummary && !moment.timingSummary.startsWith("No timed")) {
    bits.push(moment.timingSummary);
  }
  bits.push("Bottom of the Ninth — AI & Sons Arcade");
  return bits.join(" · ");
}

export function themeColorsFor(themeId: string): {
  background: string;
  panel: string;
  accent: string;
  score: string;
  warning: string;
} {
  return BROADCAST_THEMES[themeId] ?? BROADCAST_THEMES.default!;
}

/** Compact score line for the radio card face. */
export function formatMomentScore(moment: BroadcastMoment): string {
  return `${moment.playerRuns} – ${moment.opponentRuns}`;
}

/** Prefer challenge → series → exhibition URL remount. */
export function shareDeepLinkFromMoment(moment: BroadcastMoment, href: string): string {
  return buildBroadcastShareUrl({
    href,
    challengeId: moment.challengeId ?? null,
    series: moment.seriesBo3 ? "bo3" : null,
  });
}
