import type { Team } from "./Teams.ts";

/**
 * Compact spoken batting order — one sentence, one live-region hit.
 * Queue as a single phrase so SR does not rattle off nine separate names.
 */
export function formatLineupNine(
  team: Pick<Team, "shortName" | "lineup">,
  options: { visiting?: boolean } = {},
): string {
  const names = team.lineup.map((p) => p.name);
  const leadoff = names[0] ?? "the leadoff hitter";
  const last = names[names.length - 1] ?? leadoff;
  const head = names.slice(0, -1).join(", ");
  const nine = names.length <= 1 ? leadoff : `${head}, and ${last}`;
  const who = options.visiting ? `visiting nine for the ${team.shortName}` : `nine for the ${team.shortName}`;
  return `Here's the ${who}: ${nine}. ${leadoff} leading off.`;
}

/** Word count stays radio-short so this is not a mid-pitch dump. */
export function lineupCardWordCount(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}
