/**
 * Season-long box-score slash — batter/pitcher lines that survive game to game.
 * Reset only when a new SeasonPersist is created. Mid-game LiveStats is seeded
 * from this blob; merge back at game end (and on closer swap for the outgoing arm).
 */

import type { BatterLine, LivePersist, PitcherLine } from "./LiveStats.ts";
import { formatAvg } from "./LiveStats.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { teamForSide } from "./PlayerSide.ts";

export interface SeasonSlashV1 {
  readonly batters: BatterLine[];
  readonly pitchers: PitcherLine[];
}

export function emptySeasonSlash(): SeasonSlashV1 {
  return { batters: [], pitchers: [] };
}

function isBatterLine(raw: unknown): raw is BatterLine {
  if (!raw || typeof raw !== "object") return false;
  const b = raw as Partial<BatterLine>;
  return (
    typeof b.name === "string" &&
    typeof b.order === "number" &&
    typeof b.ab === "number" &&
    typeof b.r === "number" &&
    typeof b.h === "number" &&
    typeof b.rbi === "number" &&
    typeof b.bb === "number" &&
    typeof b.k === "number"
  );
}

function isPitcherLine(raw: unknown): raw is PitcherLine {
  if (!raw || typeof raw !== "object") return false;
  const p = raw as Partial<PitcherLine>;
  return (
    typeof p.name === "string" &&
    typeof p.outs === "number" &&
    typeof p.h === "number" &&
    typeof p.r === "number" &&
    typeof p.er === "number" &&
    typeof p.bb === "number" &&
    typeof p.k === "number" &&
    typeof p.pitches === "number" &&
    typeof p.strikes === "number"
  );
}

export function isSeasonSlash(raw: unknown): raw is SeasonSlashV1 {
  if (!raw || typeof raw !== "object") return false;
  const s = raw as Partial<SeasonSlashV1>;
  if (!Array.isArray(s.batters) || !Array.isArray(s.pitchers)) return false;
  return s.batters.every(isBatterLine) && s.pitchers.every(isPitcherLine);
}

function upsertNamed<T extends { name: string }>(list: readonly T[], line: T): T[] {
  const next = list.filter((item) => item.name !== line.name);
  next.push(line);
  return next;
}

export function upsertSlashPitcher(
  slash: SeasonSlashV1 | undefined,
  line: PitcherLine,
): SeasonSlashV1 {
  const base = slash ?? emptySeasonSlash();
  return {
    batters: base.batters.map((b) => ({ ...b })),
    pitchers: upsertNamed(base.pitchers, { ...line }),
  };
}

/** Overlay current box lines onto season totals (by player name). */
export function mergeSlashFromLive(
  slash: SeasonSlashV1 | undefined,
  live: Pick<LivePersist, "awayBatters" | "homeBatters" | "awayPitcher" | "homePitcher">,
): SeasonSlashV1 {
  let batters = (slash ?? emptySeasonSlash()).batters.map((b) => ({ ...b }));
  let pitchers = (slash ?? emptySeasonSlash()).pitchers.map((p) => ({ ...p }));
  for (const b of live.awayBatters) batters = upsertNamed(batters, { ...b });
  for (const b of live.homeBatters) batters = upsertNamed(batters, { ...b });
  pitchers = upsertNamed(pitchers, { ...live.awayPitcher });
  pitchers = upsertNamed(pitchers, { ...live.homePitcher });
  return { batters, pitchers };
}

export function batterFromSlash(slash: SeasonSlashV1 | undefined, name: string): BatterLine | undefined {
  return slash?.batters.find((b) => b.name === name);
}

export function pitcherFromSlash(slash: SeasonSlashV1 | undefined, name: string): PitcherLine | undefined {
  return slash?.pitchers.find((p) => p.name === name);
}

/** Spoken once at season game start once there are real ABs. */
export function describePlayerSeasonAverage(
  slash: SeasonSlashV1 | undefined,
  playerSide: PlayerSide,
): string | null {
  if (!slash) return null;
  const team = teamForSide(playerSide);
  let h = 0;
  let ab = 0;
  for (const player of team.lineup) {
    const line = batterFromSlash(slash, player.name);
    if (!line) continue;
    h += line.h;
    ab += line.ab;
  }
  if (ab < 1) return null;
  return `Your season average sits at ${formatAvg(h, ab)}.`;
}
