import type { AudioEngine } from "../AudioEngine.ts";
import type { SampleId } from "../SampleBank.ts";
import { FIELD_POSITIONS, applyEnvelope, noiseBurst, spatialPanner } from "./shared.ts";
import { clamp } from "../../timing/Timeline.ts";

/**
 * Ball into the catcher's mitt.
 *
 * Prefers glove samples; synth slap + pocket is the fallback. Velocity still
 * scales brightness/level so a heater pops harder than a curve.
 */

const GLOVE_SAMPLES: readonly SampleId[] = ["glove-1", "glove-2", "glove-3", "glove-4"];

export function playGlovePop(engine: AudioEngine, at: number, velocityMph: number): void {
  const heat = clamp((velocityMph - 78) / 22, 0, 1);
  const id = engine.samples.pick(GLOVE_SAMPLES);
  if (id) {
    const played = engine.samples.play(engine, id, {
      bus: "field",
      at,
      gain: 1.15 + 0.45 * heat,
      pan: 0.05,
      playbackRate: 0.92 + heat * 0.18,
      fadeIn: 0,
    });
    if (played) {
      playGloveSynth(engine, at, heat, 0.4);
      return;
    }
  }

  playGloveSynth(engine, at, heat);
}

function playGloveSynth(engine: AudioEngine, at: number, heat: number, levelScale = 1): void {
  const { ctx } = engine;

  const panner = spatialPanner(ctx, FIELD_POSITIONS.catcher);
  panner.connect(engine.busInput("field"));

  noiseBurst(engine, panner, {
    at,
    duration: 0.03 + 0.012 * (1 - heat),
    color: "white",
    frequency: 900 + 900 * heat,
    q: 0.7,
    peak: (0.55 + 0.45 * heat) * levelScale,
    attack: 0.001,
  });

  const pocket = ctx.createOscillator();
  pocket.type = "sine";
  pocket.frequency.setValueAtTime(210 + 60 * heat, at);
  pocket.frequency.exponentialRampToValueAtTime(95, at + 0.08);

  const pocketGain = ctx.createGain();
  pocket.connect(pocketGain);
  pocketGain.connect(panner);
  const end = applyEnvelope(pocketGain.gain, {
    at,
    attack: 0.003,
    decay: 0.085,
    peak: (0.4 + 0.3 * heat) * levelScale,
  });
  pocket.start(at);
  pocket.stop(end + 0.05);
}
