import type { BaseState } from "./GameState.ts";
import type { PlayResult } from "./OutcomeResolver.ts";
import type { Rng } from "./PitchSelector.ts";

/**
 * Baserunners — pure advancement logic.
 *
 * Kept separate from `GameState` because it is the one part of the game that
 * benefits from exhaustive property testing (runs scored should never exceed
 * runners plus the batter, bases-empty plays should never score, and so on) and
 * mixing that with the count/outs bookkeeping in `GameState` would make those
 * properties harder to state and check.
 *
 * Every function takes an `Rng` and is deterministic given one, so the same
 * seeded-RNG testing approach used for `OutcomeResolver` applies here.
 */

export type AdvanceNote = "double-play" | "sac-fly" | "productive-out" | null;

export interface AdvanceResult {
  bases: BaseState;
  runsScored: number;
  /** Outs beyond the batter's own — the second half of a double play. */
  extraOuts: number;
  note: AdvanceNote;
}

const EMPTY_BASES: BaseState = { first: false, second: false, third: false };

/**
 * Force-advance on a walk or hit-by-pitch.
 *
 * A walk only pushes a runner up when the base behind him is filled — a runner on
 * second with first base open does not move. The force can chain: bases loaded
 * pushes the runner on third home.
 */
export function advanceOnWalk(bases: BaseState): AdvanceResult {
  if (!bases.first) {
    return { bases: { ...bases, first: true }, runsScored: 0, extraOuts: 0, note: null };
  }
  if (!bases.second) {
    return { bases: { first: true, second: true, third: bases.third }, runsScored: 0, extraOuts: 0, note: null };
  }
  if (!bases.third) {
    return { bases: { first: true, second: true, third: true }, runsScored: 0, extraOuts: 0, note: null };
  }
  // Bases loaded: the force reaches all the way home.
  return { bases: { first: true, second: true, third: true }, runsScored: 1, extraOuts: 0, note: null };
}

/**
 * A ball hit safely, advancing the batter `basesGained` bases (1 = single,
 * 2 = double, 4 = home run — this game does not model triples).
 *
 * Existing runners advance *at least* `basesGained`, with some scattered further
 * on singles and doubles: a runner does not mechanically move the same distance
 * as the batter, he reads the ball and the fielder. Modelling that as "usually
 * scores, sometimes holds" rather than a fixed rule is what makes a two-out single
 * with a runner on second feel different from a leadoff single with a runner on
 * second, the way it actually should.
 */
export function advanceOnHit(
  bases: BaseState,
  basesGained: 1 | 2 | 4,
  rng: Rng,
  /** Batter speed factor — 1.0 is average; >1 more aggressive first-to-third / score from 2nd. */
  speedFactor = 1,
): AdvanceResult {
  if (basesGained === 4) {
    const runsScored = countRunners(bases) + 1; // every runner, plus the batter
    return { bases: EMPTY_BASES, runsScored, extraOuts: 0, note: null };
  }

  let runsScored = 0;
  const spd = Math.max(0.75, Math.min(1.35, speedFactor));

  // Runner originally on third: always scores on a hit, regardless of how many
  // bases the batter takes.
  if (bases.third) runsScored++;

  // Runner originally on second — the runner who can block the one behind him.
  let leadRunnerHeldAtThird = false;
  if (bases.second) {
    // A double sends a runner from second home in the overwhelming majority of
    // cases; a single is a genuine coin flip that depends on speed and the throw.
    // When a runner is also coming from first, the defense's calculus only gets
    // worse, so on a double with two runners moving the lead runner always goes —
    // holding him there would leave nowhere legal for the trailing runner to stop,
    // since the batter is himself standing on second.
    const bothRunnersMoving = basesGained === 2 && bases.first;
    const sendChance = basesGained === 2 ? (bothRunnersMoving ? 1 : 0.94) : Math.min(0.92, 0.62 * spd);
    if (rng() < sendChance) runsScored++;
    else leadRunnerHeldAtThird = true;
  }

  // Runner originally on first. He can never advance past whatever base the lead
  // runner ends up on — the two cannot occupy the same base, and a trailing runner
  // can't pass the man in front of him.
  let trailingRunnerAtSecond = false;
  let trailingRunnerAtThird = false;
  if (bases.first) {
    if (basesGained === 2) {
      // leadRunnerHeldAtThird is never true here (see bothRunnersMoving above), so
      // third is always open for this runner to reach.
      if (rng() < 0.45) runsScored++;
      else trailingRunnerAtThird = true;
    } else if (leadRunnerHeldAtThird) {
      // Blocked at third by the runner ahead of him — holds at second, exactly
      // where a runner advancing one base on a single ends up anyway.
      trailingRunnerAtSecond = true;
    } else if (rng() < Math.min(0.55, 0.35 * spd)) {
      trailingRunnerAtThird = true;
    } else {
      trailingRunnerAtSecond = true;
    }
  }

  const next: BaseState = {
    first: basesGained === 1, // the batter, if his hit was a single
    second: basesGained === 2 || trailingRunnerAtSecond,
    third: leadRunnerHeldAtThird || trailingRunnerAtThird,
  };

  return { bases: next, runsScored, extraOuts: 0, note: null };
}

/**
 * A ball put in play and caught or thrown out.
 *
 * Deliberately not a full defensive simulation — no fielder positions, no arm
 * strength — just the handful of situational rules that make a batted-out at-bat
 * read as baseball rather than as a coin flip: the double play, the sacrifice fly,
 * and the productive ground ball that moves a runner up.
 */
export function advanceOnBattedOut(
  bases: BaseState,
  play: Extract<PlayResult, "ground-out" | "fly-out" | "line-out" | "pop-up">,
  outsBefore: number,
  rng: Rng,
): AdvanceResult {
  const canTurnTwo = outsBefore < 2 && bases.first;
  const canScoreOnFly = outsBefore < 2 && bases.third;

  switch (play) {
    case "pop-up":
      // Too shallow to tag on. Nobody moves.
      return { bases, runsScored: 0, extraOuts: 0, note: null };

    case "fly-out": {
      if (canScoreOnFly && rng() < 0.55) {
        return {
          bases: { ...bases, third: false },
          runsScored: 1,
          extraOuts: 0,
          note: "sac-fly",
        };
      }
      return { bases, runsScored: 0, extraOuts: 0, note: null };
    }

    case "line-out": {
      // A sharp liner right at the fielder occasionally catches a runner leaning
      // and doubles him off — much rarer than a grounder into a real double play,
      // because the runner usually has no reason to break early on a line drive.
      if (canTurnTwo && rng() < 0.15) {
        return { bases: { ...bases, first: false }, runsScored: 0, extraOuts: 1, note: "double-play" };
      }
      return { bases, runsScored: 0, extraOuts: 0, note: null };
    }

    case "ground-out": {
      if (canTurnTwo && rng() < 0.45) {
        return { bases: { ...bases, first: false }, runsScored: 0, extraOuts: 1, note: "double-play" };
      }
      // No double play. With a runner on third and fewer than two outs, a grounder
      // to the right side (or a slow enough roller) is a classic way to bring the
      // run in even though the batter is out — the "productive out".
      if (canScoreOnFly && rng() < 0.45) {
        return { bases: { ...bases, third: false }, runsScored: 1, extraOuts: 0, note: "productive-out" };
      }
      return { bases, runsScored: 0, extraOuts: 0, note: null };
    }
  }
}

function countRunners(bases: BaseState): number {
  return Number(bases.first) + Number(bases.second) + Number(bases.third);
}

/** How a broadcaster would describe who's on. */
export function formatBases(bases: BaseState): string {
  const { first, second, third } = bases;
  if (!first && !second && !third) return "bases empty";
  if (first && second && third) return "bases loaded";
  if (first && second && !third) return "runners on first and second";
  if (first && !second && third) return "runners on the corners";
  if (!first && second && third) return "runners on second and third";
  if (first) return "runner on first";
  if (second) return "runner on second";
  return "runner on third";
}

export function runnersInScoringPosition(bases: BaseState): boolean {
  return bases.second || bases.third;
}

export function runnerCount(bases: BaseState): number {
  return countRunners(bases);
}
