/**
 * Per-game home/away assignment for series / season / playoff.
 *
 * Club identity stays on PlayerSide: "home" = Pirates, "away" = Phillies.
 * Contest home is who bats last this game. Even-numbered series (and season)
 * games flip the host so the venue copy matches GameState.
 */

import type { Score } from "./GameState.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { seriesGameVenue, seriesResultFromScore, type SeriesGameResult } from "./SeriesState.ts";
import { AWAY_TEAM, HOME_TEAM, type Team } from "./Teams.ts";

export interface ContestTeams {
  readonly home: Team;
  readonly away: Team;
  /** Which club (Pirates=home, Phillies=away) is GameState home tonight. */
  readonly contestHomeClub: PlayerSide;
}

/** Pirates host odd games for the player's club; even games flip. */
export function contestHomeClubForGame(playerSide: PlayerSide, gameNumber: number): PlayerSide {
  return seriesGameVenue(playerSide, gameNumber).hostClub;
}

/**
 * Host club for a 1-based campaign game number. Missing/invalid → Pirates host
 * (exhibition / challenges).
 */
export function contestHomeForGameNumber(
  playerSide: PlayerSide,
  gameNumber: number | null | undefined,
): PlayerSide {
  if (!gameNumber || gameNumber < 1) return "home";
  return contestHomeClubForGame(playerSide, gameNumber);
}

export function contestHomeFromHomeTeamName(homeTeam: string): PlayerSide {
  return homeTeam === AWAY_TEAM.shortName ? "away" : "home";
}

export function teamsForContestHome(contestHomeClub: PlayerSide): ContestTeams {
  if (contestHomeClub === "home") {
    return { home: HOME_TEAM, away: AWAY_TEAM, contestHomeClub };
  }
  return { home: AWAY_TEAM, away: HOME_TEAM, contestHomeClub };
}

/** GameState home/away slot occupied by a club this contest. */
export function clubToContestSide(club: PlayerSide, contestHomeClub: PlayerSide): PlayerSide {
  return club === contestHomeClub ? "home" : "away";
}

export function runsForClub(
  score: Score,
  club: PlayerSide,
  contestHomeClub: PlayerSide,
): number {
  return score[clubToContestSide(club, contestHomeClub)];
}

export function playerScoreSplitContest(
  score: Score,
  playerSide: PlayerSide,
  contestHomeClub: PlayerSide,
): { playerRuns: number; opponentRuns: number } {
  const opponent: PlayerSide = playerSide === "home" ? "away" : "home";
  return {
    playerRuns: runsForClub(score, playerSide, contestHomeClub),
    opponentRuns: runsForClub(score, opponent, contestHomeClub),
  };
}

/**
 * Map a GameState score onto club-keyed series results (winsHome = Pirates).
 * When Phillies host, GameState.home is the away club.
 */
export function seriesResultFromContest(
  score: Score,
  contestHomeClub: PlayerSide,
): SeriesGameResult {
  const raw = seriesResultFromScore(score);
  if (raw === "tie" || contestHomeClub === "home") return raw;
  return raw === "home" ? "away" : "home";
}

export function isClubShortName(name: string): boolean {
  return name === HOME_TEAM.shortName || name === AWAY_TEAM.shortName;
}
