/**
 * Bullpen — thin "Call the closer" beat (BR-8).
 *
 * One named closer per club, simple starter fatigue, at most one human pen call
 * per game. Fatigue is narrative (+ a small stuff/command dip for AI batters);
 * it does not punish human release windows mid-AB.
 */

import type { PitcherRatings } from "./Player.ts";

/** Tunable fatigue / availability knobs. */
export const BULLPEN_CONFIG = {
  /** Pitches thrown before the starter is "laboring". */
  pitchFatigue: 85,
  /** Inning where the arm starts to look tired (booth). */
  fatigueInning: 8,
  /** From this inning on, closer is callable in a save (even if fresh). */
  lateCallInning: 8,
  /** Stuff drop while an arm is fatigued (AI batter pressure). */
  fatiguedStuffPenalty: 8,
  /** Command drop while fatigued. */
  fatiguedCommandPenalty: 5,
  /** Closer labors after a short outing — not a multi-inning I-win button. */
  closerFatiguePitches: 22,
  /** Classic save window: fielding club ahead by this many (inclusive). */
  saveLeadMin: 1,
  saveLeadMax: 3,
} as const;

export interface BullpenPersist {
  /** Pitches thrown by the current home arm this appearance. */
  homePitches: number;
  /** Pitches thrown by the current away arm this appearance. */
  awayPitches: number;
  /** True once the human has pressed Call the closer this game. */
  humanCallUsed: boolean;
  /** True once home closer has entered (human or AI). */
  homeCloserIn: boolean;
  /** True once away closer has entered. */
  awayCloserIn: boolean;
  /** Booth already said the home starter is laboring. */
  homeFatigueAnnounced: boolean;
  /** Booth already said the away starter is laboring. */
  awayFatigueAnnounced: boolean;
}

export function createBullpenState(): BullpenPersist {
  return {
    homePitches: 0,
    awayPitches: 0,
    humanCallUsed: false,
    homeCloserIn: false,
    awayCloserIn: false,
    homeFatigueAnnounced: false,
    awayFatigueAnnounced: false,
  };
}

export function isValidBullpenPersist(raw: unknown): raw is BullpenPersist {
  if (!raw || typeof raw !== "object") return false;
  const b = raw as Partial<BullpenPersist>;
  return (
    typeof b.homePitches === "number" &&
    typeof b.awayPitches === "number" &&
    typeof b.humanCallUsed === "boolean" &&
    typeof b.homeCloserIn === "boolean" &&
    typeof b.awayCloserIn === "boolean" &&
    typeof b.homeFatigueAnnounced === "boolean" &&
    typeof b.awayFatigueAnnounced === "boolean"
  );
}

export function restoreBullpen(raw: unknown): BullpenPersist {
  if (isValidBullpenPersist(raw)) {
    return {
      homePitches: Math.max(0, Math.floor(raw.homePitches)),
      awayPitches: Math.max(0, Math.floor(raw.awayPitches)),
      humanCallUsed: raw.humanCallUsed,
      homeCloserIn: raw.homeCloserIn,
      awayCloserIn: raw.awayCloserIn,
      homeFatigueAnnounced: raw.homeFatigueAnnounced,
      awayFatigueAnnounced: raw.awayFatigueAnnounced,
    };
  }
  return createBullpenState();
}

/** Starter is laboring — booth + soft rating dip. */
export function isStarterFatigued(
  pitches: number,
  inning: number,
  config: typeof BULLPEN_CONFIG = BULLPEN_CONFIG,
): boolean {
  return pitches >= config.pitchFatigue || inning >= config.fatigueInning;
}

/** Fielding club's run lead (negative if behind). */
export function fieldingLead(
  score: { home: number; away: number },
  fieldingSide: "home" | "away",
): number {
  return fieldingSide === "home" ? score.home - score.away : score.away - score.home;
}

/**
 * Save / hold window — closer is a late-lead arm, not a blowout or comeback button.
 * Ahead 1–3 in a late frame, or tied in the 9th / extras.
 */
export function isSaveSituation(args: {
  inning: number;
  regulationInnings: number;
  score: { home: number; away: number };
  fieldingSide: "home" | "away";
  config?: typeof BULLPEN_CONFIG;
}): boolean {
  const config = args.config ?? BULLPEN_CONFIG;
  const lead = fieldingLead(args.score, args.fieldingSide);
  if (lead >= config.saveLeadMin && lead <= config.saveLeadMax) return true;
  const extrasOrNinth = args.inning >= Math.max(args.regulationInnings, 9);
  return lead === 0 && extrasOrNinth;
}

function isLateFrame(
  inning: number,
  regulationInnings: number,
  config: typeof BULLPEN_CONFIG,
): boolean {
  if (inning >= config.lateCallInning) return true;
  if (regulationInnings < config.lateCallInning && inning >= regulationInnings) return true;
  return false;
}

/**
 * Whether the closer call is available for the fielding club.
 * Late innings + a save/hold window. Short games unlock on the final scheduled inning.
 */
export function canCallCloser(args: {
  inning: number;
  pitches: number;
  regulationInnings: number;
  closerAlreadyIn: boolean;
  score: { home: number; away: number };
  fieldingSide: "home" | "away";
  config?: typeof BULLPEN_CONFIG;
}): boolean {
  if (args.closerAlreadyIn) return false;
  const config = args.config ?? BULLPEN_CONFIG;
  if (!isLateFrame(args.inning, args.regulationInnings, config)) return false;
  return isSaveSituation({
    inning: args.inning,
    regulationInnings: args.regulationInnings,
    score: args.score,
    fieldingSide: args.fieldingSide,
    config,
  });
}

/** Human button: available only if the pen call is still unused. */
export function canHumanCallCloser(args: {
  inning: number;
  pitches: number;
  regulationInnings: number;
  closerAlreadyIn: boolean;
  humanCallUsed: boolean;
  score: { home: number; away: number };
  fieldingSide: "home" | "away";
  config?: typeof BULLPEN_CONFIG;
}): boolean {
  if (args.humanCallUsed) return false;
  return canCallCloser(args);
}

/** AI manager: ninth (or final) inning only, tired starter, save window. */
export function shouldAiCallCloser(args: {
  inning: number;
  pitches: number;
  regulationInnings: number;
  closerAlreadyIn: boolean;
  score: { home: number; away: number };
  fieldingSide: "home" | "away";
  config?: typeof BULLPEN_CONFIG;
}): boolean {
  if (args.closerAlreadyIn) return false;
  const config = args.config ?? BULLPEN_CONFIG;
  const lateFrame =
    args.inning >= Math.min(9, Math.max(args.regulationInnings, config.lateCallInning));
  if (!lateFrame) return false;
  if (!isStarterFatigued(args.pitches, args.inning, config)) return false;
  return isSaveSituation({
    inning: args.inning,
    regulationInnings: args.regulationInnings,
    score: args.score,
    fieldingSide: args.fieldingSide,
    config,
  });
}

/** Starter or closer laboring — closer tires on a short pitch count. */
export function isArmFatigued(
  pitches: number,
  inning: number,
  closerIn: boolean,
  config: typeof BULLPEN_CONFIG = BULLPEN_CONFIG,
): boolean {
  if (closerIn) return pitches >= config.closerFatiguePitches;
  return isStarterFatigued(pitches, inning, config);
}

/** Soft stuff/command dip for a fatigued starter or a closer who's been out too long. */
export function applyFatigueToRatings(
  ratings: PitcherRatings,
  fatigued: boolean,
  config: typeof BULLPEN_CONFIG = BULLPEN_CONFIG,
): PitcherRatings {
  if (!fatigued) return ratings;
  return {
    velocity: ratings.velocity,
    stuff: Math.max(40, ratings.stuff - config.fatiguedStuffPenalty),
    command: Math.max(40, ratings.command - config.fatiguedCommandPenalty),
  };
}

export function pitchesForSide(state: BullpenPersist, side: "home" | "away"): number {
  return side === "home" ? state.homePitches : state.awayPitches;
}

export function closerInForSide(state: BullpenPersist, side: "home" | "away"): boolean {
  return side === "home" ? state.homeCloserIn : state.awayCloserIn;
}

export function fatigueAnnouncedForSide(state: BullpenPersist, side: "home" | "away"): boolean {
  return side === "home" ? state.homeFatigueAnnounced : state.awayFatigueAnnounced;
}

export function recordPitchThrown(state: BullpenPersist, side: "home" | "away"): BullpenPersist {
  if (side === "home") return { ...state, homePitches: state.homePitches + 1 };
  return { ...state, awayPitches: state.awayPitches + 1 };
}

export function markFatigueAnnounced(state: BullpenPersist, side: "home" | "away"): BullpenPersist {
  if (side === "home") return { ...state, homeFatigueAnnounced: true };
  return { ...state, awayFatigueAnnounced: true };
}

/**
 * Enter the closer for a side. Resets that side's pitch counter.
 * `byHuman` consumes the single human pen call for the game.
 */
export function enterCloser(
  state: BullpenPersist,
  side: "home" | "away",
  byHuman: boolean,
): BullpenPersist {
  const next: BullpenPersist = {
    ...state,
    ...(side === "home"
      ? { homeCloserIn: true, homePitches: 0, homeFatigueAnnounced: false }
      : { awayCloserIn: true, awayPitches: 0, awayFatigueAnnounced: false }),
  };
  if (byHuman) next.humanCallUsed = true;
  return next;
}

export function fatigueBoothLine(pitcherName: string, pitches: number): string {
  if (pitches >= BULLPEN_CONFIG.pitchFatigue) {
    return `${pitcherName} is laboring a bit — pitch count climbing.`;
  }
  return `${pitcherName} looks like he's fading as we get late.`;
}

export function closerEntryLine(closerName: string, teamShort: string, byHuman: boolean): string {
  if (byHuman) {
    return `Save situation — they're going to the pen. Here's ${closerName} for the ${teamShort}.`;
  }
  return `Save situation. The ${teamShort} call on ${closerName} from the bullpen.`;
}

export function penEmptyLine(): string {
  return "The pen is empty — you've already made your call.";
}
